inline void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    activity[var] += inc;
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }
    vsids.update(var);
}
